**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    vector<int> d(n - 1);
    for (int i = 0; i < n - 1; i++)
        d[i] = T[i + 1] - T[i];

    int maxDl = 1, maxStart = 0;
    int curDl = 1, curStart = 0;

    for (int i = 1; i < (int)d.size(); i++) {
        if (d[i] >= d[i - 1]) {
            curDl++;
        } else {
            if (curDl > maxDl) { maxDl = curDl; maxStart = curStart; }
            curDl = 1; curStart = i;
        }
    }
    if (curDl > maxDl) { maxDl = curDl; maxStart = curStart; }

    int elDl = maxDl + 1;

    cout << "a) Dlugosc: " << elDl
         << ", pozycja poczatkowa: " << maxStart + 1 << endl;
    cout << "b) Elementy:";
    for (int i = maxStart; i < maxStart + elDl; i++)
        cout << " " << T[i];
    cout << endl;
    cout << "c) Roznice:";
    for (int i = maxStart; i < maxStart + maxDl; i++)
        cout << " " << d[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Sprowadzamy problem do szukania najdluzszego niemalejacego fragmentu w tablicy roznic. Kazdy taki fragment roznic o dlugosci k odpowiada k+1 elementom oryginalnego ciagu.

Weryfikacja (dane: 2,5,7,6,8,11,15,20,26,33,30,32,35,39,44):
Roznice d[0..13]: 3,2,-1,2,3,4,5,6,7,-3,2,3,4,5

Fragmenty niemalejace (d[i] >= d[i-1]):
- d[0]=3: start. curDl=1.
- d[1]=2: 2>=3? NIE. maxDl=1, maxStart=0. Reset: curDl=1, curStart=1.
- d[2]=-1: -1>=2? NIE. Reset: curDl=1, curStart=2.
- d[3]=2: 2>=-1? TAK. curDl=2.
- d[4]=3: 3>=2? TAK. curDl=3.
- d[5]=4: TAK. curDl=4.
- d[6]=5: TAK. curDl=5.
- d[7]=6: TAK. curDl=6.
- d[8]=7: TAK. curDl=7.
- d[9]=-3: -3>=7? NIE. maxDl=7, maxStart=2. Reset: curDl=1, curStart=9.
- d[10]=2: 2>=-3? TAK. curDl=2.
- d[11]=3: TAK. curDl=3.
- d[12]=4: TAK. curDl=4.
- d[13]=5: TAK. curDl=5.
Po petli: curDl=5 < maxDl=7.

Najdluzszy: 7 roznic od indeksu 2 -> 8 elementow od T[2]=7: 7,6,8,11,15,20,26,33, poz.3.
